CREATE proc [dbo].[UspGetDSNoOnIssuance]@StoreId as int, @DSId as int as select Dsmb.DSNo,Dsmb.Date,i.Item,i.ItemId,U.Uid,U.Unit,(Dsdb.Qty - isnull((select sum(Qty) from IssuanceDetail_Store where DSId = Dsmb.DSId and ItemId = i.ItemId),0)) as Qty,Cast(isnull(Round((isnull([dbo].uspGetItemAvgRateFunc(@StoreId,i.ItemId,null,null,0),0))/(select isnull(IssFactor,0) from ItemUnit where ItemId=i.ItemId),2),0) AS DECIMAL (18,2))as Rate,Dsdb.Status, (select isnull(IssFactor,0) from ItemUnit where ItemId=i.ItemId) as Factor from DemandSheetMaster_Branch Dsmb inner join  DemandSheetDetail_Branch Dsdb on Dsdb.DSId=Dsmb.DSId inner join  Item i on i.ItemId=Dsdb.ItemId inner join  Unit u on u.UId=Dsdb.Unit where Dsmb.DSId = @DSId order by DSNo